package com.bank.removeif;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class RemoveIfTest {

    @Test
    void forEach_remove_throwsCME() {
        List<String> accounts = new ArrayList<>(List.of("SAV2001", "CLOSED-001", "CUR3001"));
        assertThatThrownBy(() -> {
            for (String acc : accounts) {
                if (acc.startsWith("CLOSED")) accounts.remove(acc);
            }
        }).isInstanceOf(ConcurrentModificationException.class);
    }

    @Test
    void iteratorRemove_safe() {
        List<String> accounts = new ArrayList<>(List.of("SAV2001", "CLOSED-001", "CUR3001"));
        Iterator<String> it = accounts.iterator();
        while (it.hasNext()) {
            if (it.next().startsWith("CLOSED")) it.remove();
        }
        assertThat(accounts).containsExactly("SAV2001", "CUR3001");
    }

    @Test
    void removeIf_cleanest() {
        List<String> accounts = new ArrayList<>(List.of("SAV2001", "CLOSED-001", "CLOSED-002", "CUR3001"));
        accounts.removeIf(acc -> acc.startsWith("CLOSED"));
        assertThat(accounts).containsExactly("SAV2001", "CUR3001");
    }

    @Test
    void removeIf_withMap() {
        Map<String, String> accounts = new HashMap<>();
        accounts.put("SAV2001", "ACTIVE");
        accounts.put("CLOSED-001", "CLOSED");
        accounts.put("CUR3001", "ACTIVE");

        accounts.entrySet().removeIf(e -> e.getValue().equals("CLOSED"));
        assertThat(accounts).hasSize(2);
        assertThat(accounts).doesNotContainKey("CLOSED-001");
    }
}
```

